#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using MassiveArmy.Industrial;
using UnityEditor;
using UnityEngine;
using UnityEngine.UIElements;
using Object=UnityEngine.Object;
using Cursor=UnityEngine.Cursor;
namespace MassiveArmy.Planetary {
 public static class InventorySlotValidation {
  [Serializable]sealed class Report {public string status="PASS",error="";public List<string> checks=new List<string>();}
  const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
  static void Set(object o,string name,object value)=>o.GetType().GetField(name,Flags).SetValue(o,value);
  static object Get(object o,string name)=>o.GetType().GetField(name,Flags).GetValue(o);
  static object Call(object o,string name,params object[] args)=>o.GetType().GetMethod(name,Flags).Invoke(o,args);
  static ItemStack Find(Inventory inventory,string id){foreach(var item in inventory.items)if(item.item==id)return item;return null;}
  [InitializeOnLoadMethod]static void Install(){EditorApplication.update-=Pump;EditorApplication.update+=Pump;}
  static void Pump(){const string request="TestResults/Survival/Inventory/request.txt";if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists(request))return;File.Delete(request);Run();}
  [MenuItem("Synthetic Front/Diagnostics/Validate shared slot inventory and equipped building")]
  public static void Run(){
   var report=new Report();GameObject host=null,cameraHost=null;PlanetDevelopment world=null;PlanetDefinition definition=null;PlanetFirstPersonController player=null;IndustrialAuthority authority=null;PersonalGameplayHud hud=null;PlayerBuildingWorld builder=null;PanelSettings settings=null;RenderTexture target=null;VisualElement root=null;int frames=0,stage=0;IndustrialWorld data=null;IndustrialActor actor=null;PlanetIndustry industry=null;int sourceSlot=-1;IndustrialMachine chest=null;var savedLock=Cursor.lockState;bool savedCursor=Cursor.visible;
   void Check(bool condition,string message){if(!condition)throw new InvalidOperationException(message);report.checks.Add(message);}
   void Capture(string name){var panel=root.panel;panel.GetType().GetMethod("ValidateLayout",Flags,null,Type.EmptyTypes,null)?.Invoke(panel,null);var repaint=panel.GetType().GetMethod("Repaint",Flags,null,new[]{typeof(Event)},null);if(repaint!=null)repaint.Invoke(panel,new object[]{new Event{type=EventType.Repaint}});else panel.GetType().GetMethod("Repaint",Flags,null,Type.EmptyTypes,null)?.Invoke(panel,null);var previous=RenderTexture.active;var image=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);try{RenderTexture.active=target;GL.Clear(true,true,Color.black);panel.GetType().GetMethod("Render",Flags,null,Type.EmptyTypes,null)?.Invoke(panel,null);RenderTexture.active=target;image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();int lit=0;foreach(var pixel in image.GetPixels32())if(pixel.r>100||pixel.g>100||pixel.b>100)lit++;File.WriteAllBytes("TestResults/Survival/Inventory/"+name+".png",image.EncodeToPNG());Check(lit>3000,"Slot UI renders readable controls: "+name);}finally{RenderTexture.active=previous;Object.DestroyImmediate(image);}}
   void Finish(){EditorApplication.update-=Tick;hud?.Dispose();builder?.Dispose();if(world!=null){Call(world,"DisposeInventoryUi");Set(world,"inventorySlotUi",null);Call(world,"DisposeRespawn");Set(world,"respawnView",null);Set(world,"industry",null);Set(world,"personalHud",null);Set(world,"player",null);}industry?.ReleaseUi();player?.Dispose();authority?.Dispose();foreach(var go in new[]{host,cameraHost})if(go!=null)Object.DestroyImmediate(go);if(definition!=null)Object.DestroyImmediate(definition);if(settings!=null)Object.DestroyImmediate(settings);if(target!=null){target.Release();Object.DestroyImmediate(target);}Cursor.lockState=savedLock;Cursor.visible=savedCursor;Directory.CreateDirectory("TestResults/Survival/Inventory");File.WriteAllText("TestResults/Survival/Inventory/editor.json",JsonUtility.ToJson(report,true));Debug.Log("Inventory slot validation "+report.status+": "+report.checks.Count+" checks");}
   void Fail(Exception e){report.status="FAIL";report.error=e.ToString();Debug.LogException(e);Finish();}
   void Drag(VisualElement source,VisualElement destination){if(source==null||destination==null)throw new InvalidOperationException("Missing drag endpoint");var down=new Event{type=EventType.MouseDown,button=0,mousePosition=source.worldBound.center};using(var evt=PointerDownEvent.GetPooled(down))source.SendEvent(evt);var up=new Event{type=EventType.MouseUp,button=0,mousePosition=destination.worldBound.center};using(var evt=PointerUpEvent.GetPooled(up))root.SendEvent(evt);}
   void Tick(){try{
    if(++frames<12)return;root.panel.GetType().GetMethod("ValidateLayout",Flags,null,Type.EmptyTypes,null)?.Invoke(root.panel,null);
    if(stage==0){
     Check(root.Q("industry-personal-materials")==null,"The player window has no second materials list");Check(root.Q("place-crafted-respawn")==null&&root.Q("deploy-sleeping-bag")==null,"The inventory has no direct Place Bag shortcut");Check(root.Q("inventory-slot-player-0-10")!=null&&root.Q("personal-slot-8")!=null,"Backpack and hotbar expose real slot drag targets");
     Capture("BeforeDrag");var before=actor.inventory.Count("copper-bar");Drag(root.Q("inventory-slot-player-0-"+sourceSlot),root.Q("personal-slot-8"));Check(actor.inventory.AtSlot(8)?.item=="copper-bar"&&actor.inventory.AtSlot(sourceSlot)==null&&actor.inventory.Count("copper-bar")==before,"UI pointer dragging moves a stack from backpack into the hotbar without copying it");world.PersonalInventory.EquippedSlot=8;Check(world.PersonalInventory.Equipped=="copper-bar","The numbered hotbar equips its actual stack");
     world.PersonalInventory.ClearMissingSlots();hud.Refresh(0,1);Capture("PlayerInventory");Drag(root.Q("personal-slot-8"),root.Q("inventory-drop-zone"));Check(actor.inventory.AtSlot(8)==null&&data.droppedItems.Count==1&&data.droppedItems[0].inventory.Count("copper-bar")==before,"Dragging to the floor zone removes the carried stack and creates recoverable loot");
     industry.OpenContainer(chest.id);Call(industry,"RefreshToolkitMenu",true);stage=1;frames=0;return;
    }
    Check(root.Q("inventory-grid-input-"+chest.id)!=null,"Placed machines and vehicle payloads show the same slot UI");Check(root.Q("inventory-slot-input-"+chest.id+"-0")!=null,"Container input slots are real drag destinations");var stone=Find(actor.inventory,"stone");long amount=stone.count;Drag(industry.MenuSurface.Q("inventory-slot-player-0-"+stone.slot),industry.MenuSurface.Q("inventory-slot-input-"+chest.id+"-0"));Check(chest.input.AtSlot(0)?.item=="stone"&&chest.input.Count("stone")==amount,"UI dragging deposits a stack into a placed container atomically");player.Inventory.ClearMissingSlots();hud.Refresh(0,1);Capture("ContainerInventory");Finish();
   }catch(Exception e){Fail(e);}}
   try{
    Directory.CreateDirectory("TestResults/Survival/Inventory");host=new GameObject("Inactive unified inventory fixture");host.SetActive(false);world=host.AddComponent<PlanetDevelopment>();world.sessionMode=PlanetGameMode.Survival;definition=ScriptableObject.CreateInstance<PlanetDefinition>();definition.bodyId=1;definition.radius=10000;definition.terrainHeight=0;world.definition=definition;var surface=new PlanetSurface(definition);Set(world,"surface",surface);var origin=new FloatingOrigin(default(UniversePosition));Set(world,"origin",origin);cameraHost=new GameObject("Inventory fixture camera");var camera=cameraHost.AddComponent<Camera>();camera.enabled=false;Set(world,"view",camera);player=new PlanetFirstPersonController(surface,origin,camera,host.transform){CaptureCursor=false};Set(world,"player",player);player.EnterBodyPosition(surface.GetSurfacePositionPrecise(Vector3.up,.05),Vector3.forward);var modes=new PlayerControlModeManager();modes.Bind(PlayerControlMode.FirstPerson,_=>{});modes.Switch(PlayerControlMode.FirstPerson);Set(world,"modes",modes);
    data=new IndustrialWorld{creativeMode=true};actor=data.Register(1,world.RespawnPose(player.PreciseBodyPosition));authority=new IndustrialAuthority(data);industry=new PlanetIndustry(world,authority);Set(industry,"surface",surface);Set(world,"industry",industry);player.Inventory.Bind(authority,1,world.PersonalItems);
    Check(world.EquipmentInventory&&player.Inventory.Items.ContainsKey("stone")&&player.Inventory.Items.ContainsKey("repair-tool"),"Personal equipment and industrial resources share one authoritative inventory");authority.ChangePersonalItem(1,"copper-bar",15,true);sourceSlot=Find(actor.inventory,"copper-bar").slot;
    string solar=IndustrialCatalog.MachineItem("solar-panel");authority.ChangePersonalItem(1,solar,2,true);authority.MoveInventory(1,new InventoryAddress{slot=Find(actor.inventory,solar).slot},new InventoryAddress{slot=5},1);player.Inventory.EquippedSlot=5;world.UpdateEquippedConstruction();Check(industry.PlacementActive,"Selecting a crafted machine in the hotbar equips its placement preview");var place=new IndustrialCommand{sequence=actor.lastSequence+1,kind="place",definition="solar-panel",pose=new FramePose{body=1,x=8,y=actor.pose.y}};Check(authority.Execute(1,place).accepted,"Equipped machine placement consumes a crafted item");world.ClearConsumedEquipment();Check(player.Inventory.Equipped==null&&actor.inventory.Count(solar)==1&&!industry.PlacementActive,"The final item in a selected nonstackable slot unequips despite another copy elsewhere");
    string foundation=IndustrialCatalog.ModuleItem("FoundationSquare");authority.ChangePersonalItem(1,foundation,20,true);authority.MoveInventory(1,new InventoryAddress{slot=Find(actor.inventory,foundation).slot},new InventoryAddress{slot=4},20);player.Inventory.EquippedSlot=4;builder=new PlayerBuildingWorld(world,surface);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,-1.7f,8));var preview=builder.PreviewForValidation(new Ray(camera.transform.position,camera.transform.forward),PlayerModuleKind.FoundationSquare);Check(preview.valid&&builder.CommitForValidation(preview,PlayerModuleKind.FoundationSquare),"A crafted foundation uses the retained socket placement and paid construction transaction");Check(actor.inventory.AtSlot(4)?.count==19&&player.Inventory.Equipped==foundation,"Stackable building pieces stay equipped while the selected stack still contains items");
    target=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGB32);target.Create();settings=Object.Instantiate(Resources.Load<PanelSettings>("MassiveArmy/UI/FrontPanel"));settings.targetTexture=target;settings.scaleMode=PanelScaleMode.ConstantPixelSize;settings.scale=1;var property=typeof(PanelSettings).GetProperty("panel",Flags)??typeof(PanelSettings).GetProperty("runtimePanel",Flags);var native=(IPanel)property.GetValue(settings);typeof(PanelSettings).GetMethod("ApplyPanelSettings",Flags,null,Type.EmptyTypes,null)?.Invoke(settings,null);root=native.visualTree;root.Clear();root.style.width=1600;root.style.height=1000;root.style.unityFont=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");hud=new PersonalGameplayHud(world,root);Set(world,"personalHud",hud);hud.ShowInventory();player.Inventory.ClearMissingSlots();hud.Refresh(0,1);
    chest=new IndustrialMachine{id=data.AllocateId(),owner=1,definition="store",pose=new FramePose{body=1,x=4,y=actor.pose.y},input=new Inventory{capacity=10000,slotLimit=-1}};data.machines.Add(chest);EditorApplication.update+=Tick;
   }catch(Exception e){Fail(e);}
  }
 }
}
#endif
